                  {%- set c_7 -%}
                    {%- set c_5 -%}
                      {{ og_text(og_get(v_c, ['tag'])) }}
                    {%- endset -%}
                    {{ include('blocks/pill.html.twig', {'p': {'tone': 'blue', 'icon': 'tag'}, 'children': og_markup(c_5)}, with_context = false) }}
                    {%- set c_6 -%}
                      {{ og_text(og_get(v_c, ['who'])) }}
                    {%- endset -%}
                    {{ include('compose/Text.html.twig', {'size': 'xs', 'class': 'text-muted-foreground', 'children': c_6}, with_context = false) }}
                  {%- endset -%}
                  {{ include('compose/Group.html.twig', {'gap': '2', 'align': 'center', 'justify': 'between', 'class': 'flex-wrap', 'children': c_7}, with_context = false) }}
                {%- endif %}
              {%- endset -%}
              {{ include('compose/ListItem.html.twig', {'class': og_s(og_cnv(['flex flex-col rounded bg-card inset-ring inset-ring-border', (og_t(og_eq(v_density, 'compact')) ? 'gap-2 p-2' : 'gap-2 p-4')])), 'attrs': og_attrs(['data-testid', 'item']), 'children': c_8}, with_context = false) }}
